import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

// Helper Components
const TabButton = ({ title, activeTab, setActiveTab }) => (
  <button type="button" onClick={() => setActiveTab(title)}
    className={`pb-2 px-2 border-b-2 font-semibold text-sm ${activeTab === title ? 'border-primary text-primary' : 'border-transparent text-subtext-light hover:border-gray-300'}`}>
    {title}
  </button>
);
const FormInput = ({ label, name, ...props }) => (
    <div>
        <label htmlFor={name} className="block text-sm font-medium text-subtext-light mb-1">{label}</label>
        <input name={name} id={name} {...props} className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md shadow-sm" />
    </div>
);
const FormSelect = ({ label, name, children, ...props }) => (
    <div>
        <label htmlFor={name} className="block text-sm font-medium text-subtext-light mb-1">{label}</label>
        <select name={name} id={name} {...props} className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md shadow-sm">{children}</select>
    </div>
);
const FileInput = ({ label, name, ...props }) => (
  <div>
    <label htmlFor={name} className="block text-sm font-medium text-subtext-light mb-1">{label}</label>
    <input type="file" name={name} id={name} {...props} className="text-sm text-subtext-light file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary/10 file:text-primary hover:file:bg-primary/20" />
  </div>
);


const AddEmployeePage = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('Personal');

  const [formData, setFormData] = useState({
    // Personal
    firstName: '', lastName: '', gender: 'Male', dateOfBirth: '', mobileNumber: '', personalEmail: '', officialEmail: '', aadharNumber: '', panNumber: '', bloodGroup: '', maritalStatus: 'Single', emergencyContactName: '', emergencyContactRelation: '', emergencyContactNumber: '', currentAddress: '', permanentAddress: '',
    // Employment
    employeeId: '', employeeType: 'Teaching', department: '', designation: '', joiningDate: '', employmentStatus: 'Active',
    // Academic
    highestQualification: '', specialization: '',
  });

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    console.log("Submitting comprehensive form data:", formData);
    try {
      await axios.post('http://127.0.0.1:8000/api/employees/', formData);
      alert('Employee added successfully!');
      navigate('/employees');
    } catch (error) {
      console.error('Error adding employee:', error.response.data);
      alert(`Failed to add staff member: ${JSON.stringify(error.response.data)}`);
    }
  };

  return (
    <div className="p-8">
      <div className="bg-card-light dark:bg-card-dark p-8 rounded-lg shadow-md">
        <h1 className="text-2xl font-bold text-text-light dark:text-text-dark mb-6">Add New Staff / Faculty</h1>

        <div className="border-b border-border-light mb-8">
          <nav className="flex space-x-4">
            <TabButton title="Personal" activeTab={activeTab} setActiveTab={setActiveTab} />
            <TabButton title="Employment" activeTab={activeTab} setActiveTab={setActiveTab} />
            {formData.employeeType === 'Teaching' && 
              <TabButton title="Academic" activeTab={activeTab} setActiveTab={setActiveTab} />
            }
            <TabButton title="Documents" activeTab={activeTab} setActiveTab={setActiveTab} />
          </nav>
        </div>

        <form onSubmit={handleSubmit}>
          {activeTab === 'Personal' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <FormInput label="First Name" name="firstName" value={formData.firstName} onChange={handleChange} required />
              <FormInput label="Last Name" name="lastName" value={formData.lastName} onChange={handleChange} required />
              <FormSelect label="Gender" name="gender" value={formData.gender} onChange={handleChange}><option>Male</option><option>Female</option><option>Other</option></FormSelect>
              <FormInput label="Date of Birth" name="dateOfBirth" type="date" value={formData.dateOfBirth} onChange={handleChange} />
              <FormInput label="Contact Number" name="mobileNumber" value={formData.mobileNumber} onChange={handleChange} required />
              <FormInput label="Personal Email" name="personalEmail" type="email" value={formData.personalEmail} onChange={handleChange} required />
              <FormInput label="Aadhar Number" name="aadharNumber" value={formData.aadharNumber} onChange={handleChange} />
              <FormInput label="PAN Number" name="panNumber" value={formData.panNumber} onChange={handleChange} />
              <FormInput label="Blood Group" name="bloodGroup" value={formData.bloodGroup} onChange={handleChange} />
              <FormSelect label="Marital Status" name="maritalStatus" value={formData.maritalStatus} onChange={handleChange}><option>Single</option><option>Married</option></FormSelect>
              <FormInput label="Emergency Contact Name" name="emergencyContactName" value={formData.emergencyContactName} onChange={handleChange} />
              <FormInput label="Emergency Contact Relation" name="emergencyContactRelation" value={formData.emergencyContactRelation} onChange={handleChange} />
              <FormInput label="Emergency Contact Number" name="emergencyContactNumber" value={formData.emergencyContactNumber} onChange={handleChange} />
            </div>
          )}
          {activeTab === 'Employment' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <FormInput label="Staff/Faculty ID" name="employeeId" value={formData.employeeId} onChange={handleChange} required />
              <FormInput label="Official Email" name="officialEmail" type="email" value={formData.officialEmail} onChange={handleChange} />
              <FormInput label="Date of Joining" name="joiningDate" type="date" value={formData.joiningDate} onChange={handleChange} required />
              <FormSelect label="Employee Type" name="employeeType" value={formData.employeeType} onChange={handleChange}>
                <option>Teaching</option><option>Non-Teaching</option>
              </FormSelect>
              <FormSelect label="Department" name="department" value={formData.department} onChange={handleChange} required>
                <option value="">-- Select Department --</option>
                <option>Faculty of Engineering</option>
                <option>Faculty of Arts & Commerce</option>
                <option>Administration</option>
                <option>Library</option>
              </FormSelect>
              <FormInput label="Designation" name="designation" value={formData.designation} onChange={handleChange} required />
              <FormSelect label="Employment Status" name="employmentStatus" value={formData.employmentStatus} onChange={handleChange}>
                <option>Active</option><option>On Leave</option><option>Resigned</option>
              </FormSelect>
            </div>
          )}
          {activeTab === 'Academic' && formData.employeeType === 'Teaching' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <FormInput label="Highest Qualification" name="highestQualification" value={formData.highestQualification} onChange={handleChange} placeholder="e.g., Ph.D in Computer Science" />
              <FormInput label="Specialization" name="specialization" value={formData.specialization} onChange={handleChange} placeholder="e.g., Artificial Intelligence" />
            </div>
          )}
          {activeTab === 'Documents' && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <FileInput label="ID Proof (Aadhar/PAN)" name="idProof" />
                <FileInput label="Address Proof" name="addressProof" />
                <FileInput label="Appointment Letter" name="appointmentLetter" />
                <FileInput label="Resume / CV" name="resume" />
                <FileInput label="Educational Certificates" name="educationalCertificates" />
                <FileInput label="Experience Certificates" name="experienceCertificates" />
            </div>
          )}

          <div className="mt-10 pt-6 border-t border-border-light flex justify-end gap-4">
            <button type="button" onClick={() => navigate('/employees')} className="bg-gray-200 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-300">Cancel</button>
            <button type="submit" className="bg-primary text-white px-6 py-2 rounded-lg hover:bg-blue-600">Save Employee</button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddEmployeePage;
